INSERT INTO tramite (numero, nombre, descripcion, institucion_id, dependencia, categoria_id, costo, tiempo, modalidad, publico, enlace_simple, enlace_tramite, imagen) VALUES
  (1, 'Anotación/inscripción de fianza', 'Servicio de inscripción de instrumentos que contengan fianzas de operadores aéreos', 1, 'Registro de Aviación Civil Salvadoreño', 'otros', '$300.00 será el monto máximo a pagar, ajustable según el monto de la fianza aplicable *(Solicitud de anotación/inscripción de fianza)*', '5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-anotacioninscripcion-de-fianza', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/126&provider=16', 'img/tramites/1058-solicitud-de-anotacioninscripcion-de-fianza.jpg'),
  (2, 'Anotación/inscripción de pólizas de seguro', 'Servicio de inscripción de documento que contenga póliza de seguro, de aeronaves u operadores aéreos', 1, 'Registro de Aviación Civil Salvadoreño', 'otros', '$60.00 al pago de la póliza se le sumará $1.00 por cada millar o fracción del monto aprobado de la póliza *(Solicitud de anotación/inscripción de pólizas de seguro)*', '5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-anotacioninscripcion-de-polizas-de-seguro', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/127&provider=16', 'img/tramites/1061-solicitud-de-anotacioninscripcion-de-polizas-de-seguro.png'),
  (3, 'Anotación/inscripción de tarifas', 'Servicio de inscripción de documentos que contengan tarifas de operadores aéreos autorizados, que pueden ser de pasajeros, carga y correo', 1, 'Registro de Aviación Civil Salvadoreño', 'otros', '$100.00 *(Solicitud de anotación/inscripción de tarifas)*', '5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-anotacioninscripcion-de-tarifas', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/128&provider=16', 'img/tramites/1060-solicitud-de-anotacioninscripcion-de-tarifas.jpg'),
  (4, 'Certificación de expedientes de aeronaves', 'Emisión de copias certificadas del expediente de aeronave de matrícula salvadoreña completo, extendidos con una razón de ser conformes al original, firmada y sellada por el Jefe del Registro de Aviación Civil', 1, 'Registro de Aviación Civil Salvadoreño', 'otros', '$20.00 *(Solicitud de certificación de expedientes de aeronaves)*', '15 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-certificacion-literal-de-documentos-anotadosinscritos', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/130&provider=16', 'img/tramites/1063-solicitud-de-certificacion-literal-de-documentos-anotadosinscritos.jpg'),
  (5, 'Certificación extractada de documentos anotados/inscritos', 'Extracto de los asientos que incluyen las marginaciones que constan en el documento inscrito', 1, 'Registro de Aviación Civil Salvadoreño', 'otros', '$20.00 *(Solicitud de certificación extractada de documentos anotados/inscritos)*', '5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-certificacion-extractada-de-documentos-anotadosinscritos', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/131&provider=16', 'img/tramites/1062-solicitud-de-certificacion-extractada-de-documentos-anotadosinscritos.jpg'),
  (6, 'Certificación literal de documentos anotados/inscritos', 'Emisión de copias certificadas del asiento de los instrumentos de que se trate, extendidos con una razón de ser conformes al original, firmada y sellada por el Jefe del Registro de Aviación Civil', 1, 'Registro de Aviación Civil Salvadoreño', 'otros', '$20.00 *(Solicitud de certificación literal de documentos anotados/inscritos)*', '15 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-certificacion-literal-de-documentos-anotadosinscritos', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/129&provider=16', 'img/tramites/1064-solicitud-de-certificacion-literal-de-documentos-anotadosinscritos.jpg'),
  (7, 'Extensión de permiso de aprendiz técnico en mantenimiento de aeronaves', 'Es la autorización otorgada por la Autoridad de Aviación Civil a una persona que le permite realizar tareas de mantenimiento de aeronaves bajo supervisión', 1, 'Autoridad de Aviación Civil (AAC)', 'otros', '$10.00 *(Modalidad única)*', '6 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/extension-de-permiso-de-aprendiz-tecnico-en-mantenimiento-de-aeronaves', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/49&provider=16', 'img/tramites/1003-extension-de-permiso-de-aprendiz-tecnico-en-mantenimiento-de-aeronaves.jpg'),
  (8, 'Extensión de permiso de piloto estudiante', 'Es el permiso que otorgada la Autoridad de Aviación Civil a una persona para realizar horas de vuelo bajo supervisión de un Instructor autorizado', 1, 'Departamento de Licencias', 'otros', '$10.00 *(Modalidad única)*', '6 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/extension-de-permiso-de-piloto-estudiante', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/79&provider=16﻿', 'img/tramites/1011-extension-de-permiso-de-piloto-estudiante.jpg'),
  (9, 'Modificación o actualización de especificaciones y limitaciones de operación (Opspecs)', 'Trámite para la modificación o sustitución del personal gerencial descrito en las especificaciones de operación de personal gerencial, gerente de estación', 1, 'Autoridad de Aviación Civil, Departamento de Certificaciones', 'otros', 'No indicado *(Modalidad única)*', '10 día hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/modificacion-o-actualizacion-de-opspecs', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/369&provider=16', 'img/tramites/1143-modificacion-o-actualizacion-de-opspecs.jpeg'),
  (10, 'Renovación de licencia de técnico de mantenimiento de aeronaves TMA', 'Renovación de Licencia de Técnico de Mantenimiento de Aeronaves TMA para efectuar los privilegios de esta en una Organización de Mantenimiento Aprobada', 1, 'Departamento de Licencias', 'otros', '$25.00 1 habilitación aeronave $35.00 2 habilitaciones (aeronave + motores) *(Ciudadano)*', '6 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/renovacion-de-licencia-tecnico-mantenimiento-de-aeronaves-tma', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/301&provider=16', 'img/tramites/1078-renovacion-de-licencia-tecnico-mantenimiento-de-aeronaves-tma.jpg'),
  (11, 'Renovación de licencia piloto privado avión', 'Acción administrativa que se realiza antes de que una licencia caduque, renueva las atribuciones de esta; permite al titular de la licencia el pilotaje de una aeronave en operaciones por las cuales no se percibe remuneración', 1, 'Departamento de Licencias', 'otros', '$30.00 1 habilitación $40.00 2 habilitaciones $50.00 3 habilitaciones *(Modalidad única)*', '2 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/renovacion-de-licencia-piloto-privado-avion', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/121&provider=16', 'img/tramites/1037-renovacion-de-licencia-piloto-privado-avion.jpeg'),
  (12, 'Renovación de permiso de aprendiz de técnico de mantenimiento de aeronaves TMA', 'Este trámite permite gestionar la renovación del permiso de aprendiz de Técnico de Mantenimiento de Aeronaves (TMA) antes de su vencimiento. Su objetivo es extender la vigencia del permiso y mantener activas las atribuciones que este otorga, conforme a la normativa aeronáutica vigente', 1, 'Departamento de Licencias', 'otros', '$10.00 *(Modalidad única)*', '2 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/renovacion-de-permiso-de-aprendiz-de-tecnico-de-mantenimiento-de-aeronaves-tma', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/117&provider=16', 'img/tramites/1040-renovacion-de-permiso-de-aprendiz-de-tecnico-de-mantenimiento-de-aeronaves-tma.jpg'),
  (13, 'Renovación de permiso de piloto estudiante', 'Trámite administrativo que se realiza antes del vencimiento de un permiso, y que permite renovar las atribuciones para continuar realizando horas de vuelo bajo la supervisión de un instructor autorizado', 1, 'Departamento de Licencias', 'otros', '$10.00 *(Modalidad única)*', '2 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/renovacion-de-permiso-de-piloto-estudiante', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/124&provider=16', 'img/tramites/1038-renovacion-de-permiso-de-piloto-estudiante.jpeg'),
  (14, 'Reposición de licencia piloto privado avión', 'Acción administrativa que se realiza por pérdida, robo o deterioro de una Licencia de piloto privado avión', 1, 'Departamento de Licencias', 'otros', '$20.00 *(Modalidad única)*', '2 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/reposicion-de-licencia-piloto-privado-avion', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/123&provider=16', 'img/tramites/1041-reposicion-de-licencia-piloto-privado-avion.jpg'),
  (15, 'Reposición de licencia técnico mantenimiento de aeronaves TMA', 'Acción administrativa que se realiza por pérdida, robo o deterioro de una licencia de técnico de mantenimiento de aeronave', 1, 'Departamento de Licencias', 'otros', '$15.00 *(Modalidad única)*', '6 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/reposicion-de-licencia-tecnico-mantenimiento-de-aeronaves-tma', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/120&provider=16', 'img/tramites/1043-reposicion-de-licencia-tecnico-mantenimiento-de-aeronaves-tma.jpg'),
  (16, 'Reposición de permiso de aprendiz de técnico de mantenimiento de aeronaves TMA', 'Acción administrativa que se realiza por pérdida, robo o deterioro de un permiso de aprendiz', 1, 'Departamento de Licencias', 'otros', '$10.00 *(Modalidad única)*', '6 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/reposicion-de-permiso-de-aprendiz-de-tecnico-de-mantenimiento-de-aeronaves-tma', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/132&provider=16', 'img/tramites/1044-reposicion-de-permiso-de-aprendiz-de-tecnico-de-mantenimiento-de-aeronaves-tma.jpg'),
  (17, 'Reposición de permiso de piloto estudiante', 'Acción administrativa que se realiza por pérdida, robo o deterioro de un Permiso de piloto estudiante', 1, 'Departamento de Licencias', 'otros', '$10.00 *(Modalidad única)*', '2 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/reposicion-de-permiso-de-piloto-estudiante', 'https://aac.ventanilla.simple.sv/login/claveunica?redirect=https://aac.ventanilla.simple.sv/tramites/iniciar/125&provider=16', 'img/tramites/1042-reposicion-de-permiso-de-piloto-estudiante.jpg'),
  (18, 'Autorización para comercializar cilindros portátiles para envasado de GLP', 'Resolución extendida por la Dirección de Hidrocarburos y Minas, que autoriza para que la persona jurídica pueda utilizar en el mercado nacional los cilindros portátiles para el envasado del GLP', 2, 'Dirección de Hidrocarburos y Minas', 'otros', 'No tiene costo *(Modalidad única)*', '22 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/utilizar-en-el-mercado-nacional-cilindros-portatiles-para-envasado-de-glp', 'https://rnpn.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/234&provider=16', 'img/tramites/1066-utilizar-en-el-mercado-nacional-cilindros-portatiles-para-envasado-de-glp.png'),
  (19, 'Autorización para comercializar reguladores de baja presión para GLP', 'Resolución extendida por la Dirección de Hidrocarburos y Minas, que autoriza para que la persona jurídica pueda comercializar en el mercado nacional reguladores de baja presión para GLP', 2, 'Dirección de Hidrocarburos y Minas', 'otros', 'No tiene costo *(Modalidad única)*', '22 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/comercializacion-local-de-reguladores-de-baja-presion-para-glp', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/234&provider=16', 'img/tramites/1069-comercializacion-local-de-reguladores-de-baja-presion-para-glp.png'),
  (20, 'Autorización para exportar GLP a granel', 'Resolución extendida por la Dirección de Hidrocarburos y Minas que autoriza a la persona jurídica a realizar la exportación de GLP a granel', 2, 'Dirección de Hidrocarburos y Minas', 'otros', 'No tiene costo *(Modalidad única)*', '22 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/exportar-glp-a-granel', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/234&provider=16', 'img/tramites/1067-exportar-glp-a-granel.png'),
  (21, 'Autorización para exportar cilindros portátiles para envasado de GLP', 'Resolución extendida por la Dirección de Hidrocarburos y Minas, que autoriza para que la persona natural pueda exportar cilindros portátiles para envasado de GLP', 2, 'Dirección General de Energía, Hidrocarburos y Minas- Dirección de Hidrocarburos y Minas', 'otros', 'No tiene costo *(Modalidad única)*', '22 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/exportar-cilindros-portatiles-para-envasado-de-glp', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/234&provider=16', 'img/tramites/1056-exportar-cilindros-portatiles-para-envasado-de-glp.png'),
  (22, 'Autorización para importación de accesorios para cilindros portátiles para GLP', 'Resolución extendida por la Dirección de Hidrocarburos y Minas, que autoriza para que la persona importe accesorios para GLP', 2, 'Dirección General de Energía, Hidrocarburos y Minas- Dirección de Hidrocarburos y Minas', 'otros', 'No tiene costo *(​Modalidad única)*', '9 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/importacion-de-accesorios-para-cilindros-portatiles-para-glp', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/234&provider=16', 'img/tramites/1057-importacion-de-accesorios-para-cilindros-portatiles-para-glp.png'),
  (23, 'Autorización para importación de válvulas para cilindros de GLP', 'Resolución extendida por la Dirección de Hidrocarburos y Minas, que autoriza para que la persona jurídica importe válvulas para GLP', 2, 'Dirección General de Energía, Hidrocarburos y Minas', 'otros', 'No tiene costo *(Modalidad única)*', '9 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/importacion-de-valvulas-para-cilindros-portatiles-para-glp', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/234&provider=16', 'img/tramites/1055-importacion-de-valvulas-para-cilindros-portatiles-para-glp.png'),
  (24, 'Autorización para importar cilindros portátiles para envasado de GLP', 'Resolución extendida por la Dirección General de Energía, Hidrocarburos y Minas, que autoriza para que la persona jurídica importe cilindros portátiles para envasado de GLP', 2, 'Recepción.', 'otros', 'No tiene costo *(Modalidad única)*', '9 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/importar-cilindros-portatiles-para-envasado-de-glp', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/234&provider=16', 'img/tramites/1050-importar-cilindros-portatiles-para-envasado-de-glp.jpg'),
  (25, 'Autorización para importar reguladores de baja presión para GLP', 'Resolución extendida por la Dirección de Hidrocarburos y Minas, mediante la cual se autoriza a la persona natural la importación de reguladores de baja presión destinados al uso de GLP', 2, 'Dirección de Hidrocarburos y Minas', 'otros', 'No tiene costo *(Modalidad única)*', '9 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/importar-reguladores-de-baja-presion-para-glp-juridico', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/234&provider=16', 'img/tramites/1065-importar-reguladores-de-baja-presion-para-glp-juridico.png'),
  (26, 'Autorización para reexportar GLP a granel', 'Trámite mediante el cual la Dirección de Hidrocarburos y Minas emite una resolución que faculta a una persona jurídica a reexportar Gas Licuado de Petróleo (GLP) a granel. Esta autorización certifica que la operación cumple con los requisitos técnicos, de seguridad y aduaneros establecidos en la normativa vigente sobre hidrocarburos y comercio exterior, garantizando una gestión responsable y legal del producto durante su tránsito hacia el país de destino', 2, 'Dirección de Hidrocarburos y Minas', 'otros', 'No tiene costo *(Modalidad única)*', '22 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/reexportar-glp-a-granel', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/234&provider=16', 'img/tramites/1068-reexportar-glp-a-granel.png'),
