  (30, 'Transferencia de Funcionamiento de Tanque para Consumo Privado', 'Resolución emitida por la Dirección General de Energía, Hidrocarburos y Minas, transfiriendo la autorización de funcionamiento de un operador a otro', 2, 'Dirección General de Energía, Hidrocarburos y Minas (DGEHM)', 'otros', 'No indicado *(Transferencia de Funcionamiento de Tanque para Consumo Privado)*', '15 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/transferencia-de-funcionamiento-de-tanque-para-consumo-privado', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/455&provider=16', 'img/tramites/1141-transferencia-de-funcionamiento-de-tanque-para-consumo-privado.png'),
  (31, 'Transferencia de Funcionamiento de Tanque para Consumo Privado Temporal', 'Resolución emitida por la Dirección General de Energía, Hidrocarburos y Minas, transfiriendo la autorización de funcionamiento de un operador a otro', 2, 'Dirección General de Energía, Hidrocarburos y Minas (DGEHM)', 'otros', 'No indicado *(Transferencia de Funcionamiento de Tanque para Consumo Privado Temporal)*', '15 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/transferencia-de-funcionamiento-de-tanque-para-consumo-privado-temporal', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/457&provider=16', 'img/tramites/1142-transferencia-de-funcionamiento-de-tanque-para-consumo-privado-temporal.png'),
  (32, 'Transferencia de funcionamiento de fábrica de cilindros para envasado', 'Resolución emitida por la Dirección General de Energía, Hidrocarburos y Minas, transfiriendo la autorización de funcionamiento de un operador a otro', 2, 'Dirección General de Energía, Hidrocarburos y Minas (DGEHM)', 'otros', 'No indicado *(Transferencia de Funcionamiento de Fábrica de Cilindros Portátiles para Envasado de GLP)*', '15 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/resolucion-emitida-por-la-direccion-general-de-energia-hidrocarburos-y-minas-transfiriendo-la-autorizacion-de-funcionamiento-de-un-operador-a-otro', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/451&provider=16', 'img/tramites/1136-resolucion-emitida-por-la-direccion-general-de-energia-hidrocarburos-y-minas-transfiriendo-la-autorizacion-de-funcionamiento-de-un-operador-a-otro.png'),
  (33, 'Transferencia de funcionamiento de taller de reparación y mantenimiento de cilindros de GLP', 'Resolución emitida por la Dirección General de Energía, Hidrocarburos y Minas, transfiriendo la autorización de funcionamiento de un operador a otro.', 2, 'Dirección General de Energía, Hidrocarburos y Minas (DGEHM)', 'otros', 'No indicado *(Transferencia de Funcionamiento de Taller de Reparación y Mantenimiento de Cilindros para GLP)*', '15 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/transferencia-de-funcionamiento-de-taller-de-reparacion-y-mantenimiento-de-cilindros-para-glp', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/453&provider=16', 'img/tramites/1139-transferencia-de-funcionamiento-de-taller-de-reparacion-y-mantenimiento-de-cilindros-para-glp.png'),
  (34, 'Transferencia de funcionamiento de taller para instalación de GLP vehicular', 'Resolución emitida por la Dirección General de Energía, Hidrocarburos y Minas, transfiriendo la autorización de funcionamiento de un operador a otro', 2, 'Dirección General de Energía, Hidrocarburos y Minas (DGEHM)', 'otros', 'No indicado *(Transferencia de Funcionamiento de Taller para Instalación de Equipos para la Utilización de GLP-V)*', '15 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/transferencia-de-funcionamiento-de-taller-para-instalacion-de-glp-vehicular', 'https://dgehm.ventanilla.simple.sv/login/claveunica?redirect=https://dgehm.ventanilla.simple.sv/tramites/iniciar/454&provider=16', 'img/tramites/1140-transferencia-de-funcionamiento-de-taller-para-instalacion-de-glp-vehicular.png'),
  (35, 'Apostillado de certificación de licencia de conducir', 'Solicitud de Apostillado electrónico de Certificación de Licencia de Conducir emitida por la Dirección General de Tránsito, con el objeto de certificar la autenticidad de la firma, la calidad en que el signatario del documento haya actuado y, en su caso, la identidad del sello o timbre del que el documento público esté revestido', 3, 'Unidad Jurídica de Tránsito, Dirección General de Tránsito', 'otros', 'No tiene costo *(Persona Natural)*', '72 horas', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/apostillado-de-certificacion-de-licencia-de-conducir', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/351&provider=16', 'img/tramites/1102-apostillado-de-certificacion-de-licencia-de-conducir.png'),
  (36, 'Apostillado de constancia de récord de licencia de conducir', 'Solicitud de Apostillado electrónico de Constancia de Récord de Licencia de Conducir emitida por la Dirección General de Tránsito, con el objeto de certificar la autenticidad de la firma, la calidad en que el signatario del documento haya actuado y, en su caso, la identidad del sello o timbre del que el documento público esté revestido', 3, 'Unidad Jurídica de Tránsito, Dirección General de Tránsito', 'otros', 'No tiene costo *(Persona Natural)*', '72 horas', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/apostillado-de-constancia-de-record-de-licencia-de-conducir', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/351&provider=16', 'img/tramites/1103-apostillado-de-constancia-de-record-de-licencia-de-conducir.png'),
  (37, 'Autorización de fianza moral', 'Este trámite permite que una persona natural mayor de edad, actuando en representación de un menor de edad debido a la ausencia de uno o ambos padres, obtenga la autorización correspondiente para la gestión de la Licencia Juvenil. Para ello, el representante deberá presentar una Fianza Moral, mediante la cual asume la responsabilidad de respaldar la autorización y el cumplimiento de las obligaciones derivadas del trámite, de conformidad con los requisitos y disposiciones legales vigentes', 3, 'Dirección General de Tránsito', 'otros', 'No tiene costo. *(Modalidad única)*', '15 día hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/autorizacion-de-fianza-moral', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/429&provider=16', 'img/tramites/378-autorizacion-de-fianza-moral.jpeg'),
  (38, 'Autorización de realización de emisión de gases', 'Este trámite es obligatorio para los usuarios que posean vehículo que se encuentra de baja en el Registro Público de Vehículos Automotores (RPVA) y se encuentren realizando el proceso de reincorporación, para los usuarios a quienes se les haya decomisado la tarjeta de circulación, hayan extraviado dicha tarjeta o que esta haya sufrido un daño irreparable que dificulte la lectura de sus datos. Este proceso permite que los vehículos sean sometidos a la prueba de emisiones de gases en un centro de emisiones de gases autorizado por el Viceministerio de Transporte, a solicitud de los usuarios', 3, 'Unidad de Medio Ambiente, de la Dirección General de Tránsito, del Viceministerio de Transporte', 'otros', '$5.00 *(Persona Natural)*', '3 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/autorizacion-de-realizacion-de-emision-de-gases', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/307&provider=16', 'img/tramites/1088-autorizacion-de-realizacion-de-emision-de-gases.jpeg'),
  (39, 'Certificación de tarifario', 'Este trámite sirve para que toda persona jurídica y natural que cuenta con una concesión o permiso para la prestación del servicio de transporte público de pasajeros tipo colectivo vigente, pueda obtener una certificación de la tarifa previamente autorizada de la ruta por la placa solicitada', 3, 'Unidad Jurídica de Transporte Terrestre', 'otros', 'No indicado *(Persona Jurídica)*', '1 a 10 días hábiles después de solicitado el trámite', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/certificacion-de-tarifario', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/349&provider=16', 'img/tramites/1127-certificacion-de-tarifario.jpeg'),
  (40, 'Constancia de capacidad', 'Determinar el peso de la tara (peso vacío), capacidad de carga y capacidad máxima permitida, dimensiones y demás características de los vehículos destinados al transporte de carga nuevos o usados, para ser inscritos en el Registro Público de Vehículos Automotores o por existir tarjetas de circulación desactualizadas, con el objeto de que la referida información sea incorporada en la tarjeta de circulación que a tal efecto emita el ente autorizado. En ese sentido se autorizarán los vehículos que estén habilitados para circular por la red vial nacional en condiciones físicas y mecánicas de manera óptima y/o requisitos en el transporte de carga', 3, 'Unidad Jurídica de Transporte de Carga', 'otros', '$39.55 *(Persona Natural)*', 'Hasta 5 días hábiles después de aprobada la inspección técnica en la Báscula seleccionada', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/constancia-de-capacidad', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/320&provider=16', 'img/tramites/1096-constancia-de-capacidad.jpeg'),
  (41, 'Constancia de modificación a la capacidad', 'Determinar el peso del vehículo cuando se ha efectuado una modificación en la cantidad de ejes descritos en la tarjeta de circulación, declaración de mercancías o Declaración Única Centroamericana, la cual puede aumentar o disminuir su capacidad en relación al peso de la tara (peso vacío), capacidad de carga y capacidad máxima permitida, aunado a ello se verifican las dimensiones y demás características de este, como resultado de una revisión técnica completa, garantizando de esta manera que cualquier modificación realizada, cumpla con los parámetros técnicos definidos por la Dirección. En ese sentido, se autorizarán los vehículos que estén habilitados para circular por la red vial nacional en condiciones físicas y mecánicas de manera óptima y/o requisitos en el transporte de carga', 3, 'Unidad Jurídica de Transporte de Carga', 'otros', '$39.55 *(Persona Natural)*', 'Hasta 5 días hábiles después de aprobada la inspección técnica en la Báscula seleccionada', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/constancia-de-modificacion-a-la-capacidad', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/320&provider=16', 'img/tramites/1097-constancia-de-modificacion-a-la-capacidad.jpeg'),
  (42, 'Constancia para la obtención de la exención de IVA', 'Este trámite sirve para que toda persona jurídica concesionaria y/ o permisionaria que realice importaciones o internaciones definitivas de autobuses, microbuses y / o vehículos de alquiler dedicados al transporte público de pasajeros pueda obtener una constancia para tramitar la exención del impuesto IVA ante la autoridad competente', 3, 'Viceministerio de Transporte', 'otros', 'No indicado *(Persona Jurídica)*', '1 a 10 días hábiles después de solicitar el trámite correspondiente', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/constancia-para-la-obtencion-de-la-exencion-de-iva', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/361&provider=16', 'img/tramites/1128-constancia-para-la-obtencion-de-la-exencion-de-iva.jpeg'),
  (43, 'Modificación física de vehículo de transporte de carga', 'Contribuir al control de datos vehiculares en cuanto al tipo y/o clase los cuales han sido modificados, asegurando que estas modificaciones cumplen o se han realizado dentro del peso o dimensiones permitidas reglamentariamente, es decir, en vehículos especiales por su número de ejes longitudinales para una distribución correcta del peso o volumen de la carga a transportar, velando por el cumplimiento de las condiciones de seguridad y/o requisitos en el transporte en la modificación física a los vehículos de carga', 3, 'Dirección Jurídica de Transporte de Carga', 'otros', '$40.00 *(Persona Natural)*', 'Hasta 5 días hábiles después de aprobada la inspección técnica en la báscula seleccionada', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/modificacion-fisica-de-vehiculo-de-transporte-de-carga', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/320&provider=16', 'img/tramites/1094-modificacion-fisica-de-vehiculo-de-transporte-de-carga.jpeg'),
  (44, 'Permiso especial para el transporte de materiales peligrosos nacional e internacional', 'Solicitud en relación cuando un vehículo de transporte de carga se dedica al transporte de materiales peligrosos, clasificado de acuerdo a la clase', 3, 'Dirección General de Transporte de Carga', 'otros', 'Clase: Camión, Panel o Pick Up $39.55 Clase: Combinación de Cabezal y Remolque $56.50 *(Persona Natural)*', 'Hasta 2 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/permiso-especial-para-el-transporte-de-materiales-peligrosos-nacional-e-internacional', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/232&provider=16', 'img/tramites/1085-permiso-especial-para-el-transporte-de-materiales-peligrosos-nacional-e-internacional.jpg'),
  (45, 'Permiso especial para el transporte de objetos que sobrepasen el peso y/o dimensiones establecidas en la ley nacional e internacional, (autorización de transporte de cargas mayores a las permitidas)', 'Solicitud requerida cuando un vehículo de transporte de carga se dedica al traslado de objetos indivisibles que sobrepasan el peso y dimensiones establecidas en la ley', 3, 'Dirección Jurídica de Transporte de Carga', 'otros', '$39.55 *(Persona Natural)*', 'Hasta 2 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/permiso-especial-para-el-transporte-de-objetos-que-sobrepasen-el-peso-yo-dimensiones-establecidas-en-la-ley-nacional-e-internacional-autorizacion-de-transporte-de-cargas-mayores-a-las-permitidas', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/309&provider=16', 'img/tramites/1086-permiso-especial-para-el-transporte-de-objetos-que-sobrepasen-el-peso-yo-dimensiones-establecidas-en-la-ley-nacional-e-internacional-autorizacion-de-transporte-de-cargas-mayores-a-las-permitidas.jpeg'),
  (46, 'Registro de transportista de carga nacional e internacional', 'Inscripción en registro con el objeto de identificar a las personas naturales o jurídicas que presten el servicio de transporte de carga por carretera', 3, 'Dirección Jurídica de Transporte de Carga', 'otros', '$28.25 *(Persona Natural)*', '1 día en horas hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/registro-de-transportista-de-carga-nacional-e-internacional', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/341&provider=16', 'img/tramites/1084-registro-de-transportista-de-carga-nacional-e-internacional.jpeg'),
  (47, 'Renovación de registro de transportistas de carga nacional e internacional', 'La renovación del Registro de Transportistas de Carga, sirve para mantener actualizada la información de las personas naturales o jurídicas que se dedican al transporte de carga por carretera, así como del parque vehicular, propietarios y los tipos de carga que transportan', 3, 'Viceministerio de Transporte', 'otros', 'No indicado *(Ciudadano)*', '5 minutos', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/renovacion-de-registro-de-transportistas-de-carga-nacional-e-internacional', 'https://vmt.ventanilla.simple.sv/login/claveunica?redirect=https://vmt.ventanilla.simple.sv/tramites/iniciar/411&provider=16', 'img/tramites/1130-renovacion-de-registro-de-transportistas-de-carga-nacional-e-internacional.jpeg'),
  (48, 'Ampliación de servicios educativos', 'Se entenderá por Ampliación a la extensión de Servicios Educativos, ofertados, a diferencia de los niveles o grados que ya tiene autorizado el centro educativo, por lo cual, debe realizarse un proceso de verificación y aseguramiento que existe la capacidad instalada para su aprobación', 4, 'Dirección General de Niveles y Modalidades Educativas', 'estudio', 'No tiene costo *(Modalidad única)*', '20 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/ampliacion-de-servicios-educativos-sector-privado', 'https://mineducyt.ventanilla.simple.sv/login/claveunica?redirect=https://mineducyt.ventanilla.simple.sv/tramites/iniciar/41&provider=16', 'img/tramites/629-ampliacion-de-servicios-educativos-sector-privado.png'),
  (49, 'Auténtica de documentos académicos', 'Es un documento por medio del cual se da fe administrativa que la firma que calza el documento se encuentra registrada como persona autorizada para emitir un documento público', 4, 'Departamento de Registro Académico', 'estudio', 'No tiene costo *(Ciudadano)*', '5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/autentica-de-documentos-academicos', 'https://mineducyt.ventanilla.simple.sv/login/claveunica?redirect=https://mineducyt.ventanilla.simple.sv/tramites/iniciar/331&provider=16', 'img/tramites/1093-autentica-de-documentos-academicos.png'),
  (50, 'Boleta de resultados PAES / AVANZO', 'Descarga digital de boleta de resultados de la prueba PAES o AVANZO para estudiantes de segundo año de bachillerato', 4, 'Dirección Nacional de Evaluación e Investigación Educativa', 'estudio', 'No tiene costo *(Ciudadano)*', '3 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/boleta-de-resultados-paes-avanzo', 'https://mineducyt.ventanilla.simple.sv/login/claveunica?redirect=https://mineducyt.ventanilla.simple.sv/tramites/iniciar/385&provider=16', 'img/tramites/1129-boleta-de-resultados-paes-avanzo.png'),
  (51, 'Cambio de domicilio centros educativos', 'Se entenderá por Cambio de Domicilio el traslado del centro educativo de la dirección autorizada para su funcionamiento a una nueva dirección y asegurar que existe la capacidad de los servicios educativos que tiene previamente aprobados', 4, 'Dirección General de Niveles y Modalidades Educativas', 'estudio', 'No tiene costo *(Modalidad única)*', '20 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/cambio-de-domicilio-centros-educativos-oficiales', 'https://mineducyt.ventanilla.simple.sv/login/claveunica?redirect=https://mineducyt.ventanilla.simple.sv/tramites/iniciar/41&provider=16', 'img/tramites/638-cambio-de-domicilio-centros-educativos-oficiales.png'),
  (52, 'Certificación de registro de notas de educación básica y media', 'Documento extendido por el Ministerio de Educación, que evidencia el grado académico obtenido por un estudiante en la república de El Salvador. Este documento tiene validez para trámite de Matricula o Presentación al lugar de trabajo', 4, 'Dirección General de Niveles y Modalidades Educativas', 'estudio', 'No tiene costo *(Ciudadano)*', '20 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/certificacion-de-registro-de-notas-de-educacion-basica-y-media', 'https://mineducyt.ventanilla.simple.sv/login/claveunica?redirect=https://mineducyt.ventanilla.simple.sv/tramites/iniciar/46&provider=16', 'img/tramites/919-certificacion-de-registro-de-notas-de-educacion-basica-y-media.png'),
  (53, 'Certificación de registro de título de educación media', 'Es el documento oficial emitido por el Ministerio de Educación, Ciencia y Tecnología por medio del cual se hace constar que existe un registro oficial de Título de Bachiller de la República de El Salvador a favor de una persona, este podrá ser solicitado en casos de extravío, destrucción o pérdida del título original', 4, 'Dirección General de Niveles y Modalidades Educativas', 'estudio', 'No tiene costo *(Modalidad única)*', '20 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/certificacion-de-registro-de-titulo-de-educacion-media', 'https://mineducyt.ventanilla.simple.sv/login/claveunica?redirect=https://mineducyt.ventanilla.simple.sv/tramites/iniciar/21&provider=16', 'img/tramites/738-certificacion-de-registro-de-titulo-de-educacion-media.png'),
  (54, 'Creación, nominación y funcionamiento de centros educativos', 'Consiste en el proceso que se realiza para la autorización de la creación, nominación y funcionamiento de un centro educativo privado, con los niveles a funcionar, su nominación y reconocimiento de director', 4, 'Dirección General de Niveles y Modalidades Educativas', 'estudio', 'No tiene costo *(Ciudadano)*', '1 día hábil', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/creacion-nominacion-y-funcionamiento-de-centros-educativos', 'https://mineducyt.ventanilla.simple.sv/login/claveunica?redirect=https://mineducyt.ventanilla.simple.sv/tramites/iniciar/41&provider=16', 'img/tramites/920-creacion-nominacion-y-funcionamiento-de-centros-educativos.png'),
  (55, 'Prospectos escolares', 'De conformidad con el artículo 82 de la Ley General de Educación, todos los centros privados de educación están en la obligación de presentar al Ministerio de Educación, el prospecto escolar anual que es el documento que evidencia el costo de la matrícula y el de cada cuota de escolaridad o colegiatura, así como el número de éstas a pagar durante el año y los servicios educativos que oferta, conforme la autorización de funcionamiento', 4, 'Dirección General de Niveles y Modalidades Educativas', 'estudio', 'No tiene costo *(Empresarial)*', '1 día hábil', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/prospectos-escolares', 'https://mineducyt.ventanilla.simple.sv/login/claveunica?redirect=https://mineducyt.ventanilla.simple.sv/tramites/iniciar/42&provider=16', 'img/tramites/921-prospectos-escolares.png'),
  (56, 'Constancia de afiliación y beneficio', 'Gestión que se realiza para solicitar una constancia de comprobación que es pensionado de vejez o sobrevivencia de ISP', 5, 'Departamento de Prestaciones', 'otros', 'No indicado *(Persona natural)*', '10 minutos', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/constancia-de-afiliacion-y-beneficio', 'https://isp.ventanilla.simple.sv/login/claveunica?redirect=https://isp.ventanilla.simple.sv/tramites/iniciar/390&provider=16', 'img/tramites/1117-constancia-de-afiliacion-y-beneficio.png'),
  (57, 'Constancia de beneficiario inscrito', 'Gestión que se realiza para solicitar los beneficiarios inscritos por el afiliado o pensionado en ISP', 5, 'Departamento de prestaciones', 'otros', 'No indicado *(Constancias de beneficiarios inscritos)*', '10 minutos', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/constancias-de-beneficiarios-inscritos', 'https://isp.ventanilla.simple.sv/login/claveunica?redirect=https://isp.ventanilla.simple.sv/tramites/iniciar/388&provider=16', 'img/tramites/1121-constancias-de-beneficiarios-inscritos.jpeg'),
  (58, 'Constancia de cotizante no pensionado', 'Gestión que se realiza para solicitar el último periodo de cotización que se tiene registrado en ISP', 5, 'Departamento de Tesorería', 'otros', 'No indicado *(Solicitud de constancias de cotizante no pensionado)*', '10 minutos', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-constancias-de-cotizante-no-pensionado', 'https://isp.ventanilla.simple.sv/login/claveunica?redirect=https://isp.ventanilla.simple.sv/tramites/iniciar/389&provider=16', 'img/tramites/1118-solicitud-de-constancias-de-cotizante-no-pensionado.jpeg'),
  (59, 'Constancia de número de afiliación', 'Gestión que se realiza para solicitar el número de afiliación que tiene asignado en ISP', 5, 'Departamento de prestaciones', 'otros', 'No indicado *(Constancia de número de afiliación)*', '10 minutos', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/constancia-de-numero-de-afiliacion', 'https://isp.ventanilla.simple.sv/login/claveunica?redirect=https://isp.ventanilla.simple.sv/tramites/iniciar/392&provider=16', 'img/tramites/1120-constancia-de-numero-de-afiliacion.jpg'),
  (60, 'Constancia de pensionado', 'Gestión que se realiza para solicitar el monto de pensión y descuentos de los pensionados en ISP', 5, 'Departamento de Prestaciones', 'otros', 'No indicado *(Constancia de pensionados)*', '10 minutos', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/constancias-de-pensionados', 'https://isp.ventanilla.simple.sv/login/claveunica?redirect=https://isp.ventanilla.simple.sv/tramites/iniciar/391&provider=16', 'img/tramites/1119-constancias-de-pensionados.jpg'),
  (61, 'Cambio de nombre del titular de la cuenta', 'Este trámite permite al usuario solicitar el cambio de nombre del titular registrado en la cuenta de un servicio de agua potable y/o alcantarillado. Es aplicable cuando, por razones legales, de compraventa, herencia u otros motivos justificables, se requiere actualizar la información del titular del servicio asociado a un inmueble', 6, 'Dirección de Ingresos y Comercialización', 'vivienda', '$2.26 *(Ciudadano)*', '3 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/solicitud-de-tramites-de-cambio-de-nombre-del-titular-de-la-cuenta', 'https://anda.ventanilla.simple.sv/login/claveunica?redirect=https://anda.ventanilla.simple.sv/tramites/iniciar/17&provider=16', 'img/tramites/881-solicitud-de-tramites-de-cambio-de-nombre-del-titular-de-la-cuenta.jpeg'),
  (62, 'Constancia de no servicio de agua potable y/o alcantarillado', 'Hace constar que el usuario no tiene cuentas de agua potable y/o alcantarillado en su inmueble con la institución. Lo puede solicitar una persona natural o jurídica', 6, 'Dirección de Ingresos y Comercialización', 'vivienda', '$3.39 *(Ciudadano)*', '1 día hábil', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/constancia-de-no-servicio-de-agua-potable-yo-alcantarillado', 'https://anda.ventanilla.simple.sv/login/claveunica?redirect=https://anda.ventanilla.simple.sv/tramites/iniciar/20&provider=16', 'img/tramites/1-constancia-de-no-servicio-de-agua-potable-yo-alcantarillado.jpeg'),
  (63, 'Factibilidad para una vivienda', 'Este trámite permite al usuario solicitar la evaluación de factibilidad técnica para la conexión de su inmueble a los servicios de agua potable y/o alcantarillado. A través de esta gestión, se determinará si es posible realizar la conexión a la red existente, considerando aspectos técnicos y de cobertura en la zona donde se encuentra ubicado el inmueble', 6, 'Dirección de Ingresos y Comercialización', 'vivienda', '$13.56 *(Ciudadano)*', '15 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/solicitud-de-tramites-de-factibilidad-para-una-vivienda', 'https://anda.ventanilla.simple.sv/login/claveunica?redirect=https://anda.ventanilla.simple.sv/tramites/iniciar/17&provider=16', 'img/tramites/880-solicitud-de-tramites-de-factibilidad-para-una-vivienda.jpeg'),
  (64, 'Solvencia de cuenta de agua potable y/o alcantarillados', 'Hace constar que el usuario no presenta saldos pendientes con la institución a la fecha de la emisión. Lo puede solicitar una persona natural o jurídica', 6, 'Dirección de Ingresos y Comercialización', 'vivienda', '$3.39 *(Ciudadano)*', '1 día hábil', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/solvencia-de-cuenta-de-agua-potable-yo-alcantarillados', 'https://anda.ventanilla.simple.sv/login/claveunica?redirect=https://anda.ventanilla.simple.sv/tramites/iniciar/18&provider=16', 'img/tramites/2-solvencia-de-cuenta-de-agua-potable-yo-alcantarillados.jpeg'),
  (65, 'Matrícula de fierro para herrar ganado', 'Los ganaderos deben de registrar sus fierros y matricularlos, ya que son los que servirán para la comprobación de la propiedad y comercialización del ganado bovino y equino, y estos deben de estar realizando los trámites respectivos, según su vigencia y demanda según sea el caso', 7, 'Área de Registro de Marcas de Animales (Marcas y fierros)', 'otros', '$21.89 Reposición de matrícula extraviada $43.79 Refrenda de matrícula para herrar ganado $90.40 Refrenda de matrícula especial para herrar ganado *(Ciudadano)*', 'Hasta 4 horas', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/solicitud-de-matricula-de-fierro-para-herrar-ganado', 'https://mag.ventanilla.simple.sv/login/claveunica?redirect=https://mag.ventanilla.simple.sv/tramites/iniciar/298&provider=16', 'img/tramites/1077-solicitud-de-matricula-de-fierro-para-herrar-ganado.png'),
  (66, 'Nota de exoneración de visado de importación de productos agrícola', 'Trámite para la facilitación de importación de productos que según código arancelario requieren visado del Ministerio de Agricultura y Ganadería, pero los cuales no son sujetos de control por parte de la División de Registro y Fiscalización Agrícola', 7, 'Ministerio de Agricultura y Ganadería', 'otros', 'No tiene costo *(Modalidad única)*', '3 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/nota-de-exoneracion-de-visado-de-importacion-de-productos-agricola', 'https://mag.ventanilla.simple.sv/login/claveunica?redirect=https://mag.ventanilla.simple.sv/tramites/iniciar/58&provider=16', 'img/tramites/1006-nota-de-exoneracion-de-visado-de-importacion-de-productos-agricola.png'),
  (67, 'Nota de exoneración de visado de importación de productos utilizados en alimentación animal', 'Trámite para la facilitación de importación de productos que según código arancelario requieren visado del Ministerio de Agricultura y Ganadería, pero los cuales no son sujetos de control por parte de la División de Registro y Fiscalización de Productos Veterinarios', 7, 'División de Registro y Fiscalización de Productos Veterinarios', 'otros', 'No tiene costo *(Modalidad única)*', '3 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/nota-de-exoneracion-de-visado-de-importacion-de-productos-veterinarios', 'https://mag.ventanilla.simple.sv/login/claveunica?redirect=https://mag.ventanilla.simple.sv/tramites/iniciar/58&provider=16', 'img/tramites/1007-nota-de-exoneracion-de-visado-de-importacion-de-productos-veterinarios.png'),
  (68, 'Notificación de asamblea general', 'Dar a conocer a los asociados sobre necesidades y tomar acuerdos sobre ingresos de asociados, elección de cuerpos directivos, presentación de estados financieros, arrendamientos, solicitud de créditos, venta de tierra u otra información', 7, 'División de Asociaciones Agropecuarias, Dirección de Economía Agropecuaria del Ministerio de Agricultura y Ganadería', 'otros', 'No tiene costo *(Modalidad Única)*', '8 horas hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/notificacion-de-asamblea-general', 'https://mag.ventanilla.simple.sv/login/claveunica?redirect=https://mag.ventanilla.simple.sv/tramites/iniciar/340&provider=16', 'img/tramites/1009-notificacion-de-asamblea-general.jpeg'),
  (69, 'Certificación técnica para fines judiciales y de seguros', 'Descripción de fenómenos naturales y su impacto en la vida humana y propiedades en determinada fecha, hora y zona geográfica, para trámites legales', 8, 'Dirección General de Observatorio Amenazas y Recursos Naturales', 'otros', 'No indicado *(Persona Natural o Jurídica)*', '10 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/certificacion-tecnica-para-fines-judiciales-y-de-seguros', 'https://marn.ventanilla.simple.sv/login/claveunica?redirect=https://marn.ventanilla.simple.sv/tramites/iniciar/408&provider=16', 'img/tramites/1125-certificacion-tecnica-para-fines-judiciales-y-de-seguros.jpeg'),
  (70, 'Información LIDAR para la investigación científica y el desarrollo experimental para los sectores de educación superior y gobierno', 'Este trámite digital permite solicitar productos geoambientales derivados de tecnología LIDAR (Light Detection and Ranging), orientados al análisis y desarrollo de investigaciones científicas o proyectos técnicos. Está dirigido a instituciones de educación superior y entidades gubernamentales que requieran esta información para fines de investigación, planificación territorial, estudios ambientales u otras aplicaciones técnicas', 8, '(Dirección General de Observatorio Ambiental y Amenazas)', 'otros', 'No tiene costo *(Modalidad única)*', 'Hasta 10 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/productos-lidar-tecnica-de-teledeteccion-optica-que-utiliza-la-luz-de-laser-para-obtener-una-muestra-densa-de-la-superficie-de-la-tierra-produciendo-mediciones-exactas-de-x-y-y-z', 'https://marn.ventanilla.simple.sv/login/claveunica?redirect=https://marn.ventanilla.simple.sv/tramites/iniciar/224&provider=16', 'img/tramites/922-productos-lidar-tecnica-de-teledeteccion-optica-que-utiliza-la-luz-de-laser-para-obtener-una-muestra-densa-de-la-superficie-de-la-tierra-produciendo-mediciones-exactas-de-x-y-y-z.jpeg'),
  (71, 'Información gratuita de fenómenos naturales', 'Este trámite permite a la ciudadanía solicitar de forma gratuita información técnica relacionada con fenómenos naturales, a través del Observatorio de Amenazas y Recursos Naturales', 8, 'Dirección de Observatorio de Amenazas y Recursos Naturales.', 'otros', 'No tiene costo *(Solicitud de Información Gratuita de Fenómenos Naturales)*', 'Hasta 5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-informacion-gratuita-de-fenomenos-naturales', 'https://marn.ventanilla.simple.sv/login/claveunica?redirect=https://marn.ventanilla.simple.sv/tramites/iniciar/118&provider=16', 'img/tramites/1051-solicitud-de-informacion-gratuita-de-fenomenos-naturales.jpeg'),
  (72, 'Permiso de incubación y recolección de huevos de tortuga marina', 'Regular las actividades, obras y proyectos relacionados con la incubación en condiciones controladas de huevos de tortugas marinas e incubación in situ de huevos de tortugas marinas por medio de la protección de playa para permitir la incubación', 8, 'Dirección General de Ecosistemas y Biodiversidad', 'otros', 'No tiene costo *(Persona natural)*', '30 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/permiso-para-la-incubacion-de-huevos-de-tortugas-marinas-en-condiciones-controladas', 'https://marn.ventanilla.simple.sv/login/claveunica?redirect=https://marn.ventanilla.simple.sv/tramites/iniciar/332&provider=16', 'img/tramites/313-permiso-para-la-incubacion-de-huevos-de-tortugas-marinas-en-condiciones-controladas.jpeg'),
  (73, 'Certificación de partidas', 'Documento emitido por el RNPN que certifica la o las partidas que se encontraron con los datos proporcionados para la búsqueda en los sistemas que esta institución administra', 9, 'Registro Nacional de las Personas Naturales', 'documentos', '$3.00 Constancia de inexistencia $3.00 Certificación de NO partida $5.00 Certificación de partida de El Salvador $8.00 Certificación de registro histórico $35.00 Certificación de partidas en el exterior *(Ciudadano)*', '24 horas hábiles a partir del ingreso del formulario de la solicitud', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/certificacion-de-partidas', 'https://rnpn.ventanilla.simple.sv/login/claveunica?redirect=https://rnpn.ventanilla.simple.sv/tramites/iniciar/93&provider=16', 'img/tramites/1034-certificacion-de-partidas.jpg'),
  (74, 'Certificación de registro de DUI y no DUI', 'Documento que reproduce y certifica el resultado de búsqueda de información contenida en el Sistema de Registro de Documento Único de Identidad o la imposibilidad de emitir dicho documento', 9, 'Unidad Jurídica Registral', 'documentos', '$5.00 *(Ciudadano)*', '1 hora hábil', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/certificacion-de-registro-de-dui-y-no-dui', 'https://rnpn.ventanilla.simple.sv/login/claveunica?redirect=https://rnpn.ventanilla.simple.sv/tramites/iniciar/88&provider=16', 'img/tramites/1030-certificacion-de-registro-de-dui-y-no-dui.jpeg'),
  (75, 'Constancia de homónimo', 'Documento en el que se expresa la existencia o no de más de un registro con el mismo nombre en los sistemas que el RNPN administra', 9, 'Unidad Jurídica Registral', 'documentos', '$10.00 *(Ciudadano)*', '1 hora hábil', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/constancia-de-homonimo', 'https://rnpn.ventanilla.simple.sv/login/claveunica?redirect=https://rnpn.ventanilla.simple.sv/tramites/iniciar/89&provider=16', 'img/tramites/1031-constancia-de-homonimo.jpg'),
  (76, 'Constancia de horarios de atención en los servicios de rehabilitación', 'Constancia otorgada por el Centro del ISRI que brinda la atención al usuario que permite informarse de los horarios y programas que son requeridos para su atención en rehabilitación', 10, 'Instituto Salvadoreño de Rehabilitación Integral', 'otros', 'No tiene costo *(Modalidad única)*', '3 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-constancia-horarios-de-atencion-en-los-servicios-de-rehabilitacion', 'https://isri.ventanilla.simple.sv/login/claveunica?redirect=https://isri.ventanilla.simple.sv/tramites/iniciar/71&provider=16', 'img/tramites/1010-solicitud-de-constancia-horarios-de-atencion-en-los-servicios-de-rehabilitacion.png'),
  (77, 'Constancia médica', 'Constancia otorgada por el Centro del ISRI que brindo la atención al usuario que permite informarse del diagnóstico médico', 10, 'Trabajo Social', 'otros', 'No tiene costo *(Modalidad única)*', '5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-constancia-medica', 'https://isri.ventanilla.simple.sv/login/claveunica?redirect=https://isri.ventanilla.simple.sv/tramites/iniciar/60&provider=16', 'img/tramites/1008-solicitud-de-constancia-medica.png'),
  (78, 'Otorgamiento de cita médica', 'Gestión que se realiza para solicitar cita médica de manera digital en cualquier centro de habilitación y rehabilitación del Instituto Salvadoreño de Rehabilitación Integral, quedando agendada la persona para el servicio de consultas médicas del Instituto', 10, 'RECEPCION ISRI', 'otros', 'No tiene costo *(Persona Natural)*', '3 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/otorgamiento-de-cita-medica', 'https://isri.ventanilla.simple.sv/login/claveunica?redirect=https://isri.ventanilla.simple.sv/tramites/iniciar/328&provider=16', 'img/tramites/1092-otorgamiento-de-cita-medica.png'),
  (79, 'Servicio VIP en el Aeropuerto Internacional de El Salvador', 'Nuestro servicio VIP en el Aeropuerto Internacional de El Salvador, San Óscar Arnulfo Romero y Galdámez (AIES-SOARG), está disponible para pasajeros que arriban o salen de El Salvador por esta vía aérea, incluye asistencia y acompañamiento personalizado por edecanes para realizar trámites migratorios y retiro de equipaje, entre otros', 11, 'Central de Anuncios / Edecanes', 'otros', '$55.00 Por cada servicio requerido/por persona ≥ de 3 años *(Modalidad única)*', '1 hora', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-del-servicio-vip-en-el-aeropuerto-internacional-de-el-salvador', 'https://cepa.ventanilla.simple.sv/login/claveunica?redirect=https://cepa.ventanilla.simple.sv/tramites/iniciar/190&provider=16', 'img/tramites/1047-solicitud-del-servicio-vip-en-el-aeropuerto-internacional-de-el-salvador.jpg'),
  (80, 'Servicio extraordinario en el Puerto de Acajutla', 'Servicios portuarios que sean requeridos en horarios no administrativos, fines de semana y días festivos, por las agencias navieras, consignatarios, consolidadores, almacenadoras y usuarios en general', 11, 'Comisión Ejecutiva Portuaria Autónoma (CEPA) – Puerto de Acajutla', 'otros', 'Varía según el servicio solicitado *(Solicitud de Servicio Extraordinario en el Puerto de Acajutla - Persona Natural)*', '1 hora', 'Presencial / En línea', 'Empresarial', 'https://www.simple.sv/tramite/solicitud-de-servicio-extraordinario-en-el-puerto-de-acajutla', 'https://cepa.ventanilla.simple.sv/login/claveunica?redirect=https://cepa.ventanilla.simple.sv/tramites/iniciar/280&provider=16', 'img/tramites/1072-solicitud-de-servicio-extraordinario-en-el-puerto-de-acajutla.png'),
  (81, 'Solicitud de carnet de identificación para el ingreso a las instalaciones de las empresas de CEPA', 'Proceso para la gestión y emisión de carnet de identificación, disponible para Instituciones del Estado, Embajadas, Organismos Internacionales, empresas contratistas, sub contratistas, concesionarios, arrendatarios u otras personas naturales o jurídicas con quienes la CEPA tiene relaciones de cooperación, contractuales y/o comerciales que requieran acceso a las instalaciones, garantizando eficiencia, transparencia y cumplimiento de las normas de seguridad y control de acceso establecidas por la CEPA', 11, 'Sección de Seguridad Física - Departamento de Seguridad Aeroportuaria', 'otros', 'Instituciones de gobierno - $0.00 *(Modalidad única)*', '1 a 5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-carnet-de-identificacion-para-el-ingreso-a-las-instalaciones-de-las-empresas-de-cepa', 'https://cepa.ventanilla.simple.sv/login/claveunica?redirect=https://cepa.ventanilla.simple.sv/tramites/iniciar/428&provider=16', 'img/tramites/1132-solicitud-de-carnet-de-identificacion-para-el-ingreso-a-las-instalaciones-de-las-empresas-de-cepa.jpg'),
  (82, 'Acreditación de programas y registro de miembros de la REA', 'La acreditación de los programas constituye la autorización administrativa para su ejecución y funcionamiento. Todo programa en materia de primera infancia, niñez y adolescencia desarrollados por instituciones privadas y organizaciones de la sociedad civil deberán ser acreditados ante el CONAPINA, solo las entidades sin fines de lucro serán registradas para formar parte de la REA', 12, 'Unidad de Registro, Autorización y Supervisión - Departamento de Acreditación, Registro de Programas y REA.', 'otros', 'No tiene costo *(CONAPINA - Acreditación de Programas y Registro de miembros de la REA (Administrativo))*', '50 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/acreditacion-de-programas-y-registro-de-miembros-de-la-rea', 'https://conapina.ventanilla.simple.sv/login/claveunica?redirect=https://conapina.ventanilla.simple.sv/tramites/iniciar/297&provider=16', 'img/tramites/1073-acreditacion-de-programas-y-registro-de-miembros-de-la-rea.jpeg'),
  (83, 'Autorización y Renovación para el Funcionamiento de Centros de Atención a la Primera Infancia (CАРІ)', 'Trámite mediante el cual se otorga la autorización oficial para el funcionamiento de Centros de Atención a la Primera Infancia, asegurando el cumplimiento de los requisitos legales, técnicos y de calidad necesarios para brindar atención integral, segura y adecuada a niñas y niños en sus primeros años de vida', 12, 'Departamento de Autorización y Registro de Centros de Atención a Primera Infancia.', 'otros', '$45.85 *(Modalidad única)*', '20 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/autorizacion-de-centros-de-atencion-a-primera-infancia', 'https://conapina.ventanilla.simple.sv/login/claveunica?redirect=https://conapina.ventanilla.simple.sv/tramites/iniciar/458&provider=16', 'img/tramites/1046-autorizacion-de-centros-de-atencion-a-primera-infancia.jpeg'),
  (84, 'Registro de proyectos de atención de primera infancia, niñez y adolescencia', 'El registro de los proyectos es una autorización administrativa para su ejecución y funcionamiento. Todas las instituciones públicas, privadas y organizaciones de la sociedad civil que desarrollen proyectos cuya población objetivo sean las niñas, niños y adolescentes, deberán informar al Consejo Nacional de la Primera Infancia, Niñez y Adolescencia una vez iniciada su ejecución, el detalle de las intervenciones a realizar y otros aspectos relevantes del proyecto a fin de articular acciones con el Sistema Nacional de Protección', 12, 'Unidad de Registro, Autorización y Supervisión - Departamento de Acreditación, Registro de Programas y REA.', 'otros', 'No tiene costo *(CONAPINA - (Administrativo))*', '20 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/registro-de-proyectos-de-atencion-de-primera-infancia-ninez-y-adolescencia', 'https://conapina.ventanilla.simple.sv/login/claveunica?redirect=https://conapina.ventanilla.simple.sv/tramites/iniciar/281&provider=16', 'img/tramites/1074-registro-de-proyectos-de-atencion-de-primera-infancia-ninez-y-adolescencia.jpeg'),
  (85, 'Certificación de notas para graduados de ENA', 'Este trámite permite a los graduados de la Escuela Nacional de Agricultura (ENA) solicitar la emisión oficial de su certificación de notas. Este documento detalla el historial académico del solicitante y puede ser requerido para fines laborales, académicos o de validación de estudios en otras instituciones', 13, 'Registro Académico', 'otros', '$10.00 *(Modalidad única)*', '5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/emision-de-certificacion-de-notas-para-graduados-de-ena', 'https://ena.ventanilla.simple.sv/login/claveunica?redirect=https://ena.ventanilla.simple.sv/tramites/iniciar/83&provider=16', 'img/tramites/1014-emision-de-certificacion-de-notas-para-graduados-de-ena.png'),
  (86, 'Constancia de estudios', 'Documento solicitado por estudiantes activos para ser utilizada en diversos trámites como: pensiones, solicitud de viáticos y seguros', 13, 'Coordinación académica', 'otros', '$5.00 *(Solicitud de Constancias de Estudios)*', '3 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-constancias-de-estudios', 'https://ena.ventanilla.simple.sv/login/claveunica?redirect=https://ena.ventanilla.simple.sv/tramites/iniciar/270&provider=16', 'img/tramites/1071-solicitud-de-constancias-de-estudios.jpg'),
  (87, 'Reingreso para la carrera de agrónomo en grado técnico', 'Proceso que se realiza para volver a ser estudiante activo de la institución después de haber estado retirado voluntariamente o por haber reprobado materias', 13, 'Coordinación Académica', 'otros', '$5.00 *(Persona Natural)*', '20 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-reingreso-para-la-carrera-de-agronomo-en-grado-tecnico', 'https://ena.ventanilla.simple.sv/login/claveunica?redirect=https://ena.ventanilla.simple.sv/tramites/iniciar/339&provider=16', 'img/tramites/1099-solicitud-de-reingreso-para-la-carrera-de-agronomo-en-grado-tecnico.jpeg'),
  (88, 'Ayuda económica por la adquisición de anteojos', 'Reembolso de máximo $100.00 dólares a otorgar al servidor público docente activo o pensionado, por la adquisición de anteojos, el cual se brinda un máximo de dos ocasiones', 14, 'Sección de Riesgos Profesionales, Beneficios y Prestaciones', 'otros', 'No indicado *(Modalidad única)*', '38 días hábiles posterior a la autorización de pago', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/ayuda-economica-por-la-adquisicion-de-anteojos', 'https://isbm.ventanilla.simple.sv/login/claveunica?redirect=https://isbm.ventanilla.simple.sv/tramites/iniciar/434&provider=16', 'img/tramites/1131-ayuda-economica-por-la-adquisicion-de-anteojos.jpeg'),
  (89, 'Beneficio de ayuda económica para gastos funerarios', 'Brindar ayuda económica para gastos funerarios a los miembros del grupo familiar del cotizante fallecido', 14, 'Sección de riesgos profesionales, beneficios y prestaciones', 'otros', 'No indicado *(Unica)*', '30 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/beneficio-de-ayuda-economica-para-gastos-funerarios', 'https://isbm.ventanilla.simple.sv/login/claveunica?redirect=https://isbm.ventanilla.simple.sv/tramites/iniciar/426&provider=16', 'img/tramites/1134-beneficio-de-ayuda-economica-para-gastos-funerarios.jpeg'),
  (90, 'Reembolsos por gastos médico-hospitalarios', 'Solicitud de trámite de reembolso (por compra de medicamento, exámenes, cirugías, consulta médica, etc)', 14, 'Sección de Riesgos Profesionales, Beneficios y Prestaciones', 'otros', 'No tiene costo *(Persona Natural)*', '1 mes hábil', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/tramite-de-reembolsos-por-gastos-medicos-hospitalarios', 'https://simple.sv/tramite/tramite-de-reembolsos-por-gastos-medicos-hospitalarios/persona-natural', 'img/tramites/1113-tramite-de-reembolsos-por-gastos-medicos-hospitalarios.jpg'),
  (91, 'Constancia de no inscrito para persona natural o jurídica como patrono en el ISSS', 'Generación de constancia de no inscrito para persona natural o jurídica como patrono en el ISSS', 15, 'Sección administración cuentas por cobrar y sección aseguramiento', 'otros', 'No tiene costo *(Solicitud de constancia de no inscrito para persona natural o jurídica como patrono en el ISSS)*', '5 minutos', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-constancia-de-no-inscrito-para-persona-natural-o-juridica-como-patrono-en-el-isss', 'https://isss.ventanilla.simple.sv/login/claveunica?redirect=https://isss.ventanilla.simple.sv/tramites/iniciar/39&provider=16', 'img/tramites/1114-solicitud-de-constancia-de-no-inscrito-para-persona-natural-o-juridica-como-patrono-en-el-isss.jpg'),
  (92, 'Solvencia patronal de régimen salud', 'Este trámite permite a los empleadores (patronos) solicitar la constancia o solvencia patronal emitida por el Instituto Salvadoreño del Seguro Social (ISSS). Esta constancia certifica que el empleador se encuentra al día en el cumplimiento de sus obligaciones legales y previsionales ante dicha institución', 15, 'Sección administración cuentas por cobrar y sección aseguramiento', 'otros', 'No tiene costo *(Solicitud de solvencia patronal de régimen salud)*', '5 minutos', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/solvencias-y-constancias-patronales', 'https://isss.ventanilla.simple.sv/login/claveunica?redirect=https://isss.ventanilla.simple.sv/tramites/iniciar/22&provider=16', 'img/tramites/999-solvencias-y-constancias-patronales.jpeg'),
  (93, 'Fijación de cuota alimenticia a obligados nacionales y residentes en el extranjero', 'El trámite para la gestión de cuotas alimenticias en el exterior inicia con la solicitud ante la Procuraduría, quien brinda información sobre los requisitos y remite la solicitud al Viceministerio de Diáspora y Movilidad Humana. Este último coordina con la representación diplomática o consular para citar al obligado y realizar las gestiones pertinentes. La Procuraduría, tras recibir el acta de comparecencia, informa al solicitante sobre el resultado y gestiona el pago de la cuota alimenticia. Los pagos se realizan mediante giros postales o transferencias electrónicas, y el cumplimiento se verifica antes de efectuar el depósito correspondiente', 16, 'Procuraduría Especializada de Familia', 'otros', 'No tiene costo *(Solicitud de fijación cuota alimenticia)*', 'Hasta 55 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-fijacion-cuota-alimenticia', 'https://pgr.ventanilla.simple.sv/login/claveunica?redirect=https://pgr.ventanilla.simple.sv/tramites/iniciar/386&provider=16', 'img/tramites/1053-solicitud-de-fijacion-cuota-alimenticia.jpg'),
  (94, 'Solvencia de pensión alimenticia de la PGR', 'Es la solicitud para emitir el documento que indica el cumplimiento o no en los pagos por pensión alimenticia de una persona', 16, 'Secretaría General', 'otros', 'No tiene costo *(Persona Natural)*', '15 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-solvencia-de-pension-alimenticia-de-la-pgr', 'https://pgr.ventanilla.simple.sv/login/claveunica?redirect=https://pgr.ventanilla.simple.sv/tramites/iniciar/348&provider=16', 'img/tramites/1101-solicitud-de-solvencia-de-pension-alimenticia-de-la-pgr.jpeg'),
  (95, 'Homónimos para registros de armas de fuego', 'Es la constancia otorgada a las personas que presentan problemas a causa de poseer nombres similares con otras personas en el sistema de registro y control de armas de fuego, impidiéndoles darles continuidad a sus trámites', 17, 'Departamento de Registro y Control de Armas de Fuego, Dirección de Logística del Ministerio de la Defensa Nacional', 'otros', 'No tiene costo *(Modalidad única)*', '30 minutos hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/constancia-de-homonimos-para-registros-de-armas-de-fuego', 'https://mdn.ventanilla.simple.sv/login/claveunica?redirect=https://mdn.ventanilla.simple.sv/tramites/iniciar/54&provider=16', 'img/tramites/1004-constancia-de-homonimos-para-registros-de-armas-de-fuego.png'),
  (96, 'Solicitud para la Devolución de Armas de Fuego de Persona Natural', 'Trámite para la devolución de arma de fuego a personas naturales que se les ha decomisado arma por haber cometido alguna infracción a la Ley CRAMEAS', 17, 'Departamento de Asesoría Legal', 'otros', 'No indicado *(Modalidad única)*', '20 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-para-la-devolucion-de-armas-de-fuego-de-persona-natural', 'https://mdn.ventanilla.simple.sv/login/claveunica?redirect=https://mdn.ventanilla.simple.sv/tramites/iniciar/462&provider=16', 'img/tramites/1133-solicitud-para-la-devolucion-de-armas-de-fuego-de-persona-natural.jpeg'),
  (97, 'Solicitud de Constancia de Publicación en el Diario Oficial', 'Gestión que se realiza para solicitar constancia de publicación que, de fe legal de la inserción de un documento específico, que aparecerá publicado en el Diario Oficial que se indica, salvo caso fortuito o fuerza mayor', 18, 'Gerencia del Diario Oficial', 'otros', '$3.25 USD *(Persona Jurídica)*', '2 días hábiles', 'Presencial / En línea', 'Empresarial', 'https://www.simple.sv/tramite/solicitud-de-constancia-de-publicacion-en-el-diario-oficial', 'https://imprentanacional.ventanilla.simple.sv/login/claveunica?redirect=https://imprentanacional.ventanilla.simple.sv/tramites/iniciar/334&provider=16', 'img/tramites/1107-solicitud-de-constancia-de-publicacion-en-el-diario-oficial.jpeg'),
  (98, 'Solicitud de publicación en Diario Oficial', 'Gestión que se realiza para publicar en el Diario Oficial diversos documentos en cumplimiento al principio de publicidad y garantizar legitimación del acto y el conocimiento a terceros interesados, imprenta', 18, 'Gerencia del Diario Oficial', 'otros', 'Costo difiere de acuerdo con tarifas establecidas *(Modalidad única)*', '15 días hábiles', 'Presencial / En línea', 'Empresarial', 'https://www.simple.sv/tramite/solicitud-de-publicacion-en-el-diario-oficial', 'https://imprentanacional.ventanilla.simple.sv/login/claveunica?redirect=https://imprentanacional.ventanilla.simple.sv/tramites/iniciar/65&provider=16', 'img/tramites/1005-solicitud-de-publicacion-en-el-diario-oficial.jpeg'),
  (99, 'Constancia de antecedentes penales', 'Constancia para comprobar que las personas naturales de origen salvadoreño, no poseen registros de antecedentes penales por sentencia condenatoria ejecutoriada en su contra por imputársele un delito', 19, 'Dirección General de Centros Penales', 'empleo', '$3.00 *(Nacionales / Personas naturales)*', '12 horas hábiles (máximo 20 días hábiles, según el caso)', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/emision-de-certificacion-de-antecedentes-penales', 'https://antecedentes.seguridad.gob.sv/servicios', 'img/tramites/8-emision-de-certificacion-de-antecedentes-penales.jpg'),
  (100, 'Constancia de antecedentes policiales', 'La presente tiene por objeto, verificar las bases de datos que para los efectos de ley consulta la Unidad de Registro y Antecedentes Policiales, en el marco de sus facultades, a efecto de hacer constar si el ciudadano/a mencionado/a presenta o no, antecedentes Policiales, entendidos estos como la existencia de registros vinculados a investigaciones, denuncias, aprehensiones en flagrancia, detenciones administrativas o judiciales', 20, 'Unidad de Registro y Antecedentes Policiales', 'empleo', '$3.50 *(Nacionales)*', '5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/constancia-de-antecedentes-policiales', 'https://pnc.ventanilla.simple.sv/login/claveunica?redirect=https://pnc.ventanilla.simple.sv/tramites/iniciar/51&provider=16', 'img/tramites/34-constancia-de-antecedentes-policiales.jpg'),
  (101, 'Consulta y pago de préstamos FSV', 'a) Estado de cuenta de préstamo: gestión que se realiza para solicitar el estado de cuenta del préstamo con un resumen detallado de la situación del préstamo y sus saldos b) Histórico de pagos de los últimos doce meses: gestión que se realiza para solicitar un informe detallado del historial de pagos de los últimos doce meses c) Histórico de pagos desde la escrituración: gestión que se realiza para solicitar el histórico de pagos desde la escrituración hasta la fecha de emisión d) Pago de cuota de préstamos: gestión para realizar el pago de la cuota de préstamo mediante tarjeta de crédito o de débito', 21, 'Área de Préstamos', 'vivienda', 'No tiene costo *(Persona Natural)*', '1 día', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/consulta-y-pago-de-prestamos-fsv', 'https://fsv.ventanilla.simple.sv/login/claveunica?redirect=https://fsv.ventanilla.simple.sv/tramites/iniciar/312&provider=16', 'img/tramites/1087-consulta-y-pago-de-prestamos-fsv.jpg'),
  (102, 'Solicitud de crédito', 'Aplicación para solicitar de créditos a los sectores comercio, servicio y producción, incluyendo actividades industriales, ingenios azucareros, agrarias, agropecuarias, agroindustriales, artesanales, culturales, o cualquier otro sector de la economía nacional', 22, 'Unidad de Créditos y Recuperación Administrativa', 'otros', 'No tiene costo *(Personas naturales y jurídicas de nacionalidad salvadoreña, domiciliadas en el territorio de la República de El Salvador)*', 'Hasta 20 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-credito', 'https://fosofamilia.ventanilla.simple.sv/login/claveunica?redirect=https://fosofamilia.ventanilla.simple.sv/tramites/iniciar/359&provider=16', 'img/tramites/1112-solicitud-de-credito.jpeg'),
  (103, 'Solvencia municipal y pago de impuestos municipales de los distritos de alcaldía Santa Ana Oeste', 'Este trámite permite a los contribuyentes, personas naturales o jurídicas, solicitar y obtener la solvencia municipal emitida por la Alcaldía de Santa Ana Oeste, la cual certifica que el solicitante se encuentra al día en el cumplimiento de sus obligaciones tributarias municipales y pagos de impuestos municipales', 23, 'Unidad Administrativa Tributaria Municipal', 'otros', '$1.80 Chalchuapa $2.10 Candelaria de la Frontera $2.42 San Sebastián Salitrillo $2.62 El Porvenir $3.00 Santiago de la Frontera $5.25 San Antonio Pajonal *(Persona Natural)*', '2 días', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/solicitud-de-solvencia-municipal-y-pago-de-impuestos-municipales-de-los-distritos-de-alcaldia-santa-ana-oeste', 'https://alcaldiasao.ventanilla.simple.sv/login/claveunica?redirect=https://alcaldiasao.ventanilla.simple.sv/tramites/iniciar/353&provider=16', 'img/tramites/1109-solicitud-de-solvencia-municipal-y-pago-de-impuestos-municipales-de-los-distritos-de-alcaldia-santa-ana-oeste.jpg'),
  (104, 'Solvencia IAIP', 'Solicitud para la emisión de documento indicando que carece de procesos administrativos pendientes y de responsabilidad administrativa dictada por Resolución Condenatoria, en el Instituto de Acceso a la Información Pública', 24, 'Gerencia Legal', 'otros', 'No tiene costo *(Persona Natural)*', '1 día', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solvencia-iaip', 'https://iaip.ventanilla.simple.sv/login/claveunica?redirect=https://iaip.ventanilla.simple.sv/tramites/iniciar/360&provider=16', 'img/tramites/1104-solvencia-iaip.jpeg'),
  (105, 'Certificado de inscripción para el registro del desarrollador parcelario', 'Es el certificado de inscripción de desarrollador parcelario que se emiten a las personas naturales y jurídicas, nacionales o extranjeras que comercialicen proyectos parcelarios', 25, 'Área de Registro de Profesionales, y Desarrolladores Parcelarios/ Unidad de Trámites y Permisos', 'vivienda', 'No tiene costo *(Ciudadano)*', '1 día hábil', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/certificado-inscripcion-de-registro-de-desarrollador-parcelario', 'https://mivi.ventanilla.simple.sv/login/claveunica?redirect=https://mivi.ventanilla.simple.sv/tramites/iniciar/81&provider=16', 'img/tramites/1012-certificado-inscripcion-de-registro-de-desarrollador-parcelario.jpeg'),
  (106, 'Autorización y registro de agentes marítimos', 'Este trámite sirve para que las personas jurídicas, se inscriban en la sección correspondiente del registro marítimo Salvadoreño (REMS) para ser designado por el armador, propietario o capitán, para realizar ante las Autoridades Marítimas, Portuarias y aduaneras las gestiones relacionadas con la atención de un buque en puerto Salvadoreño', 26, 'Gerencia de Regulación Marítima', 'otros', 'No tiene costo *(Modalidad única)*', '20 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/autorizacion-y-registro-de-agentes-maritimos', 'https://simple.sv/tramite/autorizacion-y-registro-de-agentes-maritimos/modalidad-unica', 'img/tramites/1000-autorizacion-y-registro-de-agentes-maritimos.png'),
  (107, 'Estado de cuenta', 'Emisión del estado de cuenta de la cartera de préstamos, provenientes de la privatización de los ingenios azucareros', 27, 'Corporación Salvadoreña de Inversiones', 'otros', 'No tiene costo *(Ciudadano)*', '30 minutos hábiles (máximo 5 días hábiles, según el caso)', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/solicitud-de-estado-de-cuenta', 'https://corsain.ventanilla.simple.sv/login/claveunica?redirect=https://corsain.ventanilla.simple.sv/tramites/iniciar/50&provider=16', 'img/tramites/1002-solicitud-de-estado-de-cuenta.jpg'),
  (108, 'Certificación de inscripción de federaciones y asociaciones deportivas', 'Solicitar certificación de inscripción de federaciones y asociaciones deportivas', 28, 'Registro Nacional de Federaciones y Asociaciones Deportivas', 'otros', 'No tiene costo *(Persona Natural y Jurídica)*', '2 días', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/certificacion-de-inscripcion-de-federaciones-y-asociaciones-deportivas', 'https://indes.ventanilla.simple.sv/login/claveunica?redirect=https://indes.ventanilla.simple.sv/tramites/iniciar/363&provider=16', 'img/tramites/1110-certificacion-de-inscripcion-de-federaciones-y-asociaciones-deportivas.jpg'),
  (109, 'Estado de cuenta del Fondo Especial de Contribuciones (FEC)', 'Solicitud de gestión para la obtención del estado de cuenta', 29, 'Unidad de Gestión de Activos del Fondo Especial', 'vivienda', 'No tiene costo *(Personal)*', '1 día hábil', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/solicitud-de-estado-de-cuenta', 'https://fonavipo.ventanilla.simple.sv/login/claveunica?redirect=https://fonavipo.ventanilla.simple.sv/tramites/iniciar/316&provider=16', 'img/tramites/1091-solicitud-de-estado-de-cuenta.png'),
  (110, 'Constancia del Tribunal de Ética Gubernamental', 'Documento en el que se expresa que personas naturales poseen o no registro de sanción por infracciones a la Ley de Ética Gubernamental, así como de procedimientos administrativos sancionadores activos o fenecidos en su contra, por posibles infracciones a la referida ley, con base en el Registro de Personas Sancionadas y los registros de la Unidad de Ética Legal del TEG', 30, 'Secretaría General', 'otros', 'No indicado *(Persona Natural)*', 'Las constancias se emitirán en un máximo de 15 días hábiles, según la naturaleza del trámite', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/constancia-del-tribunal-de-etica-gubernamental-sobre-existencia-o-no-de-sanciones-procedimientos-activos-o-fenecidos-por-infracciones-a-la-ley-de-etica-gubernamental', 'https://teg.ventanilla.simple.sv/login/claveunica?redirect=https://teg.ventanilla.simple.sv/tramites/iniciar/412&provider=16', 'img/tramites/1126-constancia-del-tribunal-de-etica-gubernamental-sobre-existencia-o-no-de-sanciones-procedimientos-activos-o-fenecidos-por-infracciones-a-la-ley-de-etica-gubernamental.jpeg'),
  (111, 'Ingreso a programas de rehabilitación', 'La solicitud de ingreso a programas de la unidad de rehabilitación, son servicios exclusivos para personas sobrevivientes lesionadas por siniestros viales en el territorio nacional, cuyo plazo máximo no haya excedido los 3 años tras ocurrido el evento. Se aclara que este trámite no es para solicitar prestaciones económicas por lesiones o fallecimiento, ni para personas cuya discapacidad no derive de un siniestro vial', 31, 'Unidad de Rehabilitación', 'otros', 'No tiene costo *(Persona Natural)*', '30 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/persona-natural', 'https://fonat.ventanilla.simple.sv/login/claveunica?redirect=https://fonat.ventanilla.simple.sv/tramites/iniciar/342&provider=16', 'img/tramites/1100-persona-natural.jpg'),
  (112, 'Constancia de cierre de casos', 'Solicitud de constancia de cierre de casos en avenimiento, conciliación, en general los cierres de casos cual sea su resolución', 32, 'Centro de Solución de Controversias', 'otros', 'No tiene costo *(Persona Natural)*', '5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/entrega-de-constancia-de-cierre-de-casos', 'https://defensoria.ventanilla.simple.sv/login/claveunica?redirect=https://defensoria.ventanilla.simple.sv/tramites/iniciar/352&provider=16', 'img/tramites/1105-entrega-de-constancia-de-cierre-de-casos.png'),
  (113, 'Constancia de no restricción migratoria', 'Es el documento que comprueba que una persona no posee restricción migratoria emitida por esta dirección general', 33, 'Departamento de Restricciones', 'documentos', 'Nacionales $10.00 Extranjeros $11.00 Tasa regulada en el Art. 325 de la LEME *(Persona Natural)*', 'A partir del cuarto día hábil, contado un día después de solicitado el trámite', 'Presencial / En línea', 'Ciudadano', 'https://www.simple.sv/tramite/constancia-de-no-restriccion', 'https://migracionyextranjeria.ventanilla.simple.sv/login/claveunica?redirect=https://migracionyextranjeria.ventanilla.simple.sv/tramites/iniciar/382&provider=16', 'img/tramites/1111-constancia-de-no-restriccion.png'),
  (114, 'Historial de pago de seguros de carácter voluntario', 'Documento que establece el detalle de todos las transacciones y pagos de primas de un seguro', 34, 'Área de Operaciones', 'otros', 'No tiene costo *(Servicio)*', '5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/historial-de-pago-de-seguros', 'https://cajamutual.ventanilla.simple.sv/login/claveunica?redirect=https://cajamutual.ventanilla.simple.sv/tramites/iniciar/346&provider=16', 'img/tramites/1098-historial-de-pago-de-seguros.png'),
  (115, 'Capacitación o consulta sobre derecho de competencia', 'Solicitud de programación de presentaciones o consultas sobre temas de competencia, casos de la Superintendencia de Competencia, etc., como parte de la ejecución de su Programa de Educación Pública sobre competencia', 35, 'Secretaría General', 'otros', 'No tiene costo *(Persona Natural)*', '2 días hábiles', 'En línea', 'Empresarial', 'https://www.simple.sv/tramite/solicitud-de-capacitacion-sobre-derecho-de-competencia', 'https://sc.ventanilla.simple.sv/login/claveunica?redirect=https://sc.ventanilla.simple.sv/tramites/iniciar/364&provider=16', 'img/tramites/1106-solicitud-de-capacitacion-sobre-derecho-de-competencia.png'),
  (116, 'Constancia de pensión de veteranos, excombatientes y beneficiarios', 'Pago de pensión a veteranos, excombatientes y personas con discapacidad a consecuencia del conflicto armado, que se encuentran censado y verificado en el registro del instituto, además de haber firmado sobrevivencia', 36, 'INABVE oficinas administrativas', 'otros', 'No indicado *(En línea)*', '6 minutos', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/constancia-de-deposito-de-pension', 'https://inabve.ventanilla.simple.sv/login/claveunica?redirect=https://inabve.ventanilla.simple.sv/tramites/iniciar/406&provider=16', 'img/tramites/1124-constancia-de-deposito-de-pension.jpg'),
  (117, 'Constancia de competencia', 'El objeto del trámite es determinar quien ejerce la competencia administrativa en las calles consultadas', 37, 'Dirección General de Caminos', 'otros', 'No tiene costo *(Modalidad única)*', '1 día hábil', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/constancia-de-competencia', 'https://mop.ventanilla.simple.sv/login/claveunica?redirect=https://mop.ventanilla.simple.sv/tramites/iniciar/387&provider=16', 'img/tramites/1115-constancia-de-competencia.png'),
  (118, 'Formulario de inscripción registro nacional de consultores', 'Este formulario permite recopilar la información necesaria para la verificación de requisitos, asegurando el cumplimiento de las normativas establecidas para la inscripción y habilitación en el Registro Nacional de Consultores', 38, 'Fondo Salvadoreño para Estudios de Preinversión - FOSEP', 'otros', 'No tiene costo *(Formulario de inscripción registro nacional de consultores)*', '5 días hábiles', 'En línea', 'Ciudadano', 'https://www.simple.sv/tramite/formulario-de-inscripcion-registro-nacional-de-consultores', 'https://foseprnc.ventanilla.simple.sv/login/claveunica?redirect=https://foseprnc.ventanilla.simple.sv/tramites/iniciar/400&provider=16', 'img/tramites/1122-formulario-de-inscripcion-registro-nacional-de-consultores.jpeg');
