INSERT INTO campo (id, paso_id, orden, tipo, nombre, etiqueta, ayuda, placeholder, valor_inicial, obligatorio, multiple, solo_lectura, modo_teclado, estilo_nota, contenido, dato_sensible) VALUES
  (1, 1, 1, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'requisitos', '{"titulo":"Creación, nominación y funcionamiento de centros educativos","lineas":["## Requisitos de infraestructura para centros educativos oficiales y privados","- Las instalaciones deben ser de uso exclusivo para la prestación de servicios educativos, contar con un aula disponible por cada grado o sección solicitado (no se autoriza grados fusionados).","- El área de recreación debe estar conforme al número de alumnos de los grados y secciones solicitados.","- Las áreas educativas deberán incluir todos los servicios necesarios para el funcionamiento del centro educativo, tales como: sala de docentes, sala de primeros auxilios, Dirección y área administrativa, así como también: laboratorio de ciencias y centro de cómputo en caso de III ciclo y Educación Media, y si el bachillerato es Técnico debe contar con los talleres o áreas equipadas para las prácticas, según la especialidad.","- La infraestructura NO deberá estar ubicada en zonas consideradas de alto riesgo, y que constituyan peligro para la seguridad física y moral o la salud mental y la vida de las niñas y los niños. Las zonas de seguridad internas deben estar señalizadas y ser del conocimiento del personal, alumnos y sus familias.","Si se solicita el Nivel de Educación Inicial deberá tomar en consideración lo siguiente:","- Si la construcción es de 2 niveles, los niños deben ubicarse en la 1ª planta.","- Las áreas verdes o similares para la recreación, esparcimiento y práctica de ejercicios de psicomotricidad deben ser adecuadas a la cantidad de estudiantes proyectados.","- Contar con una normativa interna para la protección integral.","- Los espacios deben ser cómodos, seguros, accesibles, adecuados y complementarios para las áreas de atención a las niñas y niños que favorezcan el libre movimiento: el salón de juego y psicomotricidad, área de gateo, el salón de descanso, la cocina para el manejo de los alimentos y espacio de aseo personal, todos con características de higiene y convivencia.","## Documentación para centros educativos privados","Aplica para creación, nominación y funcionamiento, ampliación de servicios y cambio de domicilio.","Persona natural:","- Documento de identificación.","Persona jurídica:","- Documento Único de Identidad (DUI), Número de Identificación Tributaria (NIT) y credencial actualizada del Representante Legal.","- Estatutos publicados, en los que haga constar que tiene como fines la educación.","Permisos:","- Calificación del lugar extendida por la Oficina de Planificación del Área Metropolitana de San Salvador (OPAMSS); en caso de no pertenecer a esta zona, se debe presentar la autorización del departamento correspondiente de la Alcaldía Municipal donde se ubica el centro educativo.","- Certificación de autorización de las condiciones de seguridad para los estudiantes, extendida por el Cuerpo de Bomberos de El Salvador. Vigente.","- Certificación de autorización de las condiciones de saneamiento ambiental, extendida por la Unidad de Salud del domicilio del centro educativo.","- El instrumento público o documento privado reconocido ante notario mediante el cual se hace la transferencia del dominio del inmueble, o documento en el que conste la posesión del inmueble.","Documentación del director (no aplica para ampliación de servicios ni cambio de domicilio):","- Documento Único de Identidad (DUI), Número de Identificación Tributaria (NIT) y Número de Identificación Profesional (NIP).","- Currículo.","- Solvencia de la Policía Nacional Civil y constancia de antecedentes penales (vigencia de 3 meses).","## Documentación para centros educativos oficiales","Persona jurídica:","- Documento Único de Identidad (DUI) y Número de Identificación Tributaria (NIT).","Permisos:","- Calificación del lugar autorizada por el departamento correspondiente de la Alcaldía Municipal donde se ubica el centro educativo.","- Certificación de autorización de las condiciones de seguridad para los estudiantes, extendida por el Cuerpo de Bomberos de El Salvador. Vigente.","- Certificación de autorización de las condiciones de saneamiento ambiental, extendida por la Unidad de Salud del domicilio del centro educativo.","- Carta de ofrecimiento de persona natural o jurídica para donación o comodato de inmueble a favor del Ministerio de Educación, cuando aplique.","## Comisión nominadora","Nombres propuestos para el centro educativo (solo aplica para creación, nominación y funcionamiento de centros educativos privados):","- Se ingresarán tres nombres propuestos en orden de prioridad, con su debida justificación; estos deben establecerse en idioma castellano, según el Reglamento para la Nominación de Centros Educativos.","La nominación o cambio de nominación podrá referirse a:","- Nombres de personajes ilustres en cualquier rama de las letras, las ciencias o las artes.","- Nombres de maestros distinguidos que hayan recibido algún tipo de mención honorífica.","Los centros educativos de educación inicial, parvularia, básica y media se sujetarán a las reglas señaladas anteriormente, pudiendo además proponer nominaciones relacionadas con valores, principios pedagógicos y frases acordes a la naturaleza de la institución educativa o al desarrollo cognitivo, en el caso de la primera infancia.","De conformidad al Artículo 98 de la Ley General de Educación es una falta muy grave funcionar sin los acuerdos de autorización y nominación correspondientes. Asimismo, el Artículo 100 del referido cuerpo legal establece que en caso de faltas graves y muy graves, las sanciones a aplicar podrán ser multas, la suspensión temporal de funcionamiento o la revocatoria de la autorización de funcionamiento."]}'::jsonb, false),
  (2, 2, 1, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'aviso', '{"titulo":"Importante","lineas":["Estimado ciudadano: los títulos de bachiller emitidos por el Ministerio de Educación, Ciencia y Tecnología a partir del año 2008 ya se encuentran debidamente autenticados en el Ministerio de Relaciones Exteriores de El Salvador y no requieren de documentos académicos adicionales."]}'::jsonb, false),
  (3, 2, 2, 'opciones', 'declara_g3', '¿Estás de acuerdo con los requisitos del trámite?', NULL, NULL, NULL, true, true, false, NULL, NULL, NULL, false),
  (4, 3, 1, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'info', '{"titulo":"Solicitud de NIE (Número de identificación del estudiante)","lineas":["Bienvenido(a) al proceso de solicitud de boleta de resultados PAES/AVANZO."]}'::jsonb, false),
  (5, 3, 2, 'opciones', 'pregunta_nie_personal', '¿Conoces tu número de NIE?', NULL, NULL, NULL, true, false, false, NULL, NULL, NULL, false),
