  (37, 6, 19, 'texto', 'institucion', 'Institución donde cursó el bachillerato', 'Escribe para buscarla. Si no aparece, escribe el nombre completo.', NULL, NULL, true, false, false, NULL, NULL, '{"sugerencias":["AHUACHAPÁN - AHUACHAPÁN - CENTRO ESCOLAR ISIDRO MENÉNDEZ","AHUACHAPÁN - AHUACHAPÁN - CENTRO ESCOLAR ALEJANDRO DE HUMBOLDT","CHALATENANGO - SANTA RITA - INSTITUTO NACIONAL SANTA RITA","AHUACHAPÁN - AHUACHAPÁN - COMPLEJO EDUCATIVO GENERAL FABIO MORÁN","AHUACHAPÁN - AHUACHAPÁN - COMPLEJO EDUCATIVO ISABEL CARRILLO DE BOLAÑOS","AHUACHAPÁN - AHUACHAPÁN - CENTRO ESCOLAR CANTÓN LOS MAGUEYES","AHUACHAPÁN - AHUACHAPÁN - COMPLEJO EDUCATIVO CANTÓN RÍO FRÍO","AHUACHAPÁN - AHUACHAPÁN - COMPLEJO EDUCATIVO DOCTOR RAFAEL MEZA DELGADO","AHUACHAPÁN - AHUACHAPÁN - COMPLEJO EDUCATIVO DOCTOR ARTURO ROMERO","AHUACHAPÁN - AHUACHAPÁN - COMPLEJO EDUCATIVO HACIENDA LA LABOR","AHUACHAPÁN - AHUACHAPÁN - INSTITUTO NACIONAL ALEJANDRO DE HUMBOLDT","AHUACHAPÁN - AHUACHAPÁN - INSTITUTO NACIONAL LUIS REYNALDO TOBAR","LA LIBERTAD - SACACOYO - INSTITUTO NACIONAL DE SACACOYO","AHUACHAPÁN - SAN FRANCISCO MENÉNDEZ - INSTITUTO NACIONAL CANTÓN CARA SUCIA","AHUACHAPÁN - APANECA - INSTITUTO NACIONAL LICENCIADO JOSÉ DANIEL CARÍAS","AHUACHAPÁN - APANECA - CENTRO ESCOLAR GENERAL FRANCISCO MENÉNDEZ","AHUACHAPÁN - ATIQUIZAYA - COMPLEJO EDUCATIVO CANTÓN IZCAQUILIO","SAN SALVADOR - APOPA - INSTITUTO NACIONAL COLONIA VALLE DEL SOL","AHUACHAPÁN - ATIQUIZAYA - INSTITUTO NACIONAL CORNELIO AZENÓN SIERRA","AHUACHAPÁN - ATIQUIZAYA - CENTRO ESCOLAR MERCEDES MONTERROSA DE CÁRCAMO","CHALATENANGO - SAN IGNACIO - INSTITUTO NACIONAL CANTÓN LAS PILAS","SANTA ANA - COATEPEQUE - INSTITUTO NACIONAL DE COATEPEQUE","SONSONATE - SONZACATE - CENTRO ESCOLAR EL SAUCE","AHUACHAPÁN - CONCEPCIÓN DE ATACO - COMPLEJO EDUCATIVO ANTONIO J. ALFARO","AHUACHAPÁN - GUAYMANGO - CENTRO ESCOLAR DE GUAYMANGO","CHALATENANGO - ARCATAO - INSTITUTO NACIONAL DE ARCATAO","MORAZÁN - YAMABAL - INSTITUTO NACIONAL DE YAMABAL","AHUACHAPÁN - JUJUTLA - COMPLEJO EDUCATIVO COLONIA NUEVA","CABAÑAS - JUTIAPA - INSTITUTO NACIONAL DE JUTIAPA","AHUACHAPÁN - EL REFUGIO - INSTITUTO NACIONAL DE EL REFUGIO","AHUACHAPÁN - SAN FRANCISCO MENÉNDEZ - COMPLEJO EDUCATIVO CANTÓN LA HACHADURA","LA PAZ - SAN MIGUEL TEPEZONTES - INSTITUTO NACIONAL DE SAN MIGUEL TEPEZONTES","AHUACHAPÁN - SAN FRANCISCO MENÉNDEZ - COMPLEJO EDUCATIVO GARITA PALMERA","AHUACHAPÁN - SAN LORENZO - COMPLEJO EDUCATIVO ABEL WILFREDO VELASCO CÁRCAMO","AHUACHAPÁN - SAN PEDRO PUXTLA - CENTRO ESCOLAR CANTÓN EL CORTEZ","SAN SALVADOR - SAN MARTÍN - COMPLEJO EDUCATIVO RESIDENCIAL ALTAVISTA","CABAÑAS - CINQUERA - INSTITUTO NACIONAL DE CINQUERA","AHUACHAPÁN - TACUBA - INSTITUTO NACIONAL LICENCIADO RENÉ PORFIRIO OSORIO","AHUACHAPÁN - TACUBA - COMPLEJO EDUCATIVO JOSÉ MARTÍ","AHUACHAPÁN - TACUBA - COMPLEJO EDUCATIVO ADELA CALDERÓN DE HERRERA","CUSCATLÁN - EL ROSARIO - INSTITUTO NACIONAL DE EL ROSARIO","SAN SALVADOR - MEJICANOS - INSTITUTO NACIONAL DE LA COLONIA SAN RAMÓN","AHUACHAPÁN - TURÍN - COMPLEJO EDUCATIVO JUAN DE DIOS DEL CID","AHUACHAPÁN - TURÍN - COMPLEJO EDUCATIVO PROFESOR RODRIGO FLORES","SANTA ANA - SANTA ANA - INSTITUTO NACIONAL CASERÍO PRIMAVERA","SANTA ANA - CANDELARIA DE LA FRONTERA - COMPLEJO EDUCATIVO BARTOLOMÉ BOLAÑOS"]}'::jsonb, false),
