  (82, 14, 1, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'info', '{"titulo":"¡Hola!","lineas":["Este trámite que está a punto de iniciar puede generar un costo variable dependiendo del documento solicitado, favor asegurarse de poseer una tarjeta de crédito o débito para realizar el pago.","El valor generado únicamente constituye un arancel por la prestación del servicio, por lo que no existe devolución del mismo."]}'::jsonb, false),
  (83, 14, 2, 'opciones', 'continuar_tramite', '¿Desea continuar con el trámite?', NULL, NULL, NULL, true, false, false, NULL, NULL, NULL, false),
  (84, 14, 3, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'aviso', '{"titulo":"¡Nota importante!","lineas":["Para la realización del trámite, el usuario debe tener en cuenta los siguientes términos:","- El trámite solicitado consiste en la búsqueda y validación de la información proporcionada. Una vez ingresado y procesado, no será posible la devolución del costo del servicio, independientemente del resultado.","- Si la información ingresada es incorrecta o inexacta, el documento será desfavorable y no procede la devolución.","- Es responsabilidad del usuario el uso de tarjetas de crédito o débito para el pago del trámite.","- La emisión del documento se basará en la información que haya sido registrada por la alcaldía municipal.","- La información ingresada en la etapa de identificación del trámite es responsabilidad del usuario.","- El plazo de respuesta es de 24 horas hábiles para el servicio de certificación de partidas."]}'::jsonb, false),
  (85, 14, 4, 'opciones', 'acepta_terminos', '¿Acepta los términos antes mencionados?', NULL, NULL, NULL, true, false, false, NULL, NULL, NULL, false),
  (86, 15, 1, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'info', '{"titulo":"¡Hola!","lineas":["Este trámite que está a punto de iniciar genera un costo de hasta $5.00 por el servicio brindado, favor asegurarse de poseer una tarjeta de crédito o débito para realizar el pago.","Este valor únicamente constituye un arancel por la prestación del servicio, sin que esto signifique la emisión de un documento favorable. En caso de que el resultado no sea favorable, no hay devolución."]}'::jsonb, false),
  (87, 15, 2, 'opciones', 'continuar_tramite', '¿Desea continuar con el trámite?', NULL, NULL, NULL, true, false, false, NULL, NULL, NULL, false),
  (88, 15, 3, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'aviso', '{"titulo":"Aceptación de términos","lineas":["Para la realización del trámite, estoy consciente y tengo en cuenta los siguientes términos:","- La información ingresada en la etapa de identificación del trámite es responsabilidad del usuario.","- El trámite solicitado consiste en la búsqueda y validación de la información proporcionada. Una vez ingresado y procesado, no será posible la devolución del costo del servicio independientemente del resultado.","- Si la información es incorrecta o inexacta, el documento será desfavorable y no procederá la devolución.","- Es responsabilidad del usuario el uso de tarjetas de crédito o débito para el pago del trámite.","Así mismo DECLARO BAJO JURAMENTO: I) Que conozco los términos y requisitos previos establecidos y en caso de estar mintiendo en la información declarada o entregando documentos alterados o falsificados, estaré infringiendo en delito de estafa informática establecido en el artículo 10 de la Ley especial contra los delitos informáticos y conexos."]}'::jsonb, false),
  (89, 15, 4, 'opciones', 'acepta_terminos', 'He leído y acepto los términos legales', NULL, NULL, NULL, true, false, false, NULL, NULL, NULL, false),
  (90, 16, 1, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'info', '{"titulo":"¡Hola!","lineas":["Este trámite que está a punto de iniciar genera un costo de $10.00 por el servicio brindado, favor asegurarse de poseer una tarjeta de crédito o débito para realizar el pago.","Este valor únicamente constituye un arancel por la prestación del servicio, por lo que no existe devolución del mismo."]}'::jsonb, false),
